export function buildInsuranceRiskSchedule(startISO = null) {
  return buildScheduleFor(INSURANCE_RISK_MODULES, startISO, INSURANCE_RISK_META.cadenceDays);
}

export function insuranceRiskProgressSummary(progress = {}) {
  return progressSummaryFor(INSURANCE_RISK_MODULES, progress);
}

export function exportInsuranceRiskCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: INSURANCE_RISK_META,
    modules: buildInsuranceRiskSchedule(startISO),
    sessionFlow: INSURANCE_RISK_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function insuranceRiskRefs() {
  const seen = new Set();
  for (const m of INSURANCE_RISK_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((INSURANCE_RISK_META.wordFirst && INSURANCE_RISK_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

